#!/usr/bin/env python3
"""
Task-scoped helper for the data-storytelling report on European economic
performance. Discovers data files in this directory, normalizes them into
(economy, year, metric, value) records, computes narrative insights, and
writes a Markdown data-story report following the data-storytelling
framework (Hook -> Setup -> Conflict -> Insight -> Resolution -> Action).
"""

import csv
import json
import math
import os
import re
import sys
from collections import Counter, defaultdict

ROOT = os.path.dirname(os.path.abspath(__file__))
DEFAULT_OUT = "european_economy_data_story.md"
OUT_NAME = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_OUT
REPORT_PATH = os.path.join(ROOT, OUT_NAME)

# --------------------------------------------------------------------------
# Vocabulary / heuristics
# --------------------------------------------------------------------------

METRIC_ALIASES = {
    "growth": ["real gdp growth", "gdp growth", "economic growth", "annual growth",
               "year on year", "yoy growth", "growth"],
    "inflation": ["inflation", "hicp", "hicsp", "consumer price", "price index", "cpi"],
    "unemployment": ["unemployment", "unemployment rate", "jobless"],
    "gdppc": ["gdp per capita", "gdp per head", "gdp per person", "per capita gdp"],
    "gdp": ["gross domestic product", "gdp"],
    "debt": ["government debt", "public debt", "debt to gdp", "debt ratio", "debt"],
    "deficit": ["budget balance", "fiscal balance", "government deficit",
                "net lending", "deficit", "fiscal", "budget"],
    "trade": ["current account", "trade balance", "exports", "imports",
              "external balance", "trade"],
    "investment": ["gross fixed capital", "capital formation", "investment", "fdi"],
    "employment": ["employment rate", "employment", "jobs"],
    "population": ["population", "inhabitants"],
    "productivity": ["productivity", "output per hour", "output per worker"],
    "consumption": ["household consumption", "final consumption", "consumption"],
    "wages": ["compensation", "earnings", "wage"],
    "interest": ["interest rate", "long-term interest", "policy rate"],
    "sentiment": ["sentiment", "confidence", "esi"],
}

METRIC_DISPLAY = {
    "growth": "Real GDP growth",
    "inflation": "Inflation (HICP)",
    "unemployment": "Unemployment rate",
    "gdppc": "GDP per capita",
    "gdp": "GDP",
    "debt": "Government debt",
    "deficit": "Fiscal balance",
    "trade": "Trade / current account",
    "investment": "Investment",
    "employment": "Employment rate",
    "population": "Population",
    "productivity": "Productivity",
    "consumption": "Consumption",
    "wages": "Wages / compensation",
    "interest": "Interest rates",
    "sentiment": "Economic sentiment",
}

METRIC_UNIT = {
    "growth": "%", "inflation": "%", "unemployment": "%", "employment": "%",
    "debt": "% of GDP", "deficit": "% of GDP", "interest": "%",
    "trade": "", "gdppc": "EUR", "gdp": "", "investment": "% of GDP",
    "population": "", "productivity": "index", "consumption": "%", "wages": "",
    "sentiment": "index",
}

COUNTRY_NAMES = [
    "germany", "france", "italy", "spain", "netherlands", "belgium", "austria",
    "ireland", "portugal", "greece", "finland", "sweden", "denmark", "poland",
    "czechia", "czech republic", "hungary", "romania", "bulgaria", "croatia",
    "slovenia", "slovakia", "lithuania", "latvia", "estonia", "luxembourg",
    "cyprus", "malta", "euro area", "euro area 20", "euro area 19", "eurozone",
    "euro zone", "european union", "eu27", "eu 27", "eu", "europe",
    "united kingdom", "uk", "switzerland", "norway", "iceland", "turkey",
    "ukraine", "albania", "serbia", "montenegro", "north macedonia",
    "bosnia and herzegovina", "moldova", "georgia", "armenia", "azerbaijan",
    "russia", "belarus", "kosovo", "san marino", "monaco", "andorra",
    "liechtenstein", "world", "oecd", "g7", "g20", "total", "all countries",
]

DISPLAY = {
    "germany": "Germany", "france": "France", "italy": "Italy", "spain": "Spain",
    "netherlands": "Netherlands", "belgium": "Belgium", "austria": "Austria",
    "ireland": "Ireland", "portugal": "Portugal", "greece": "Greece",
    "finland": "Finland", "sweden": "Sweden", "denmark": "Denmark",
    "poland": "Poland", "czechia": "Czechia", "czech republic": "Czechia",
    "hungary": "Hungary", "romania": "Romania", "bulgaria": "Bulgaria",
    "croatia": "Croatia", "slovenia": "Slovenia", "slovakia": "Slovakia",
    "lithuania": "Lithuania", "latvia": "Latvia", "estonia": "Estonia",
    "luxembourg": "Luxembourg", "cyprus": "Cyprus", "malta": "Malta",
    "euro area": "Euro area", "euro area 19": "Euro area",
    "euro area 20": "Euro area", "eurozone": "Euro area",
    "euro zone": "Euro area", "european union": "EU", "eu27": "EU-27",
    "eu 27": "EU-27", "eu": "EU", "europe": "Europe",
    "united kingdom": "United Kingdom", "uk": "United Kingdom",
    "switzerland": "Switzerland", "norway": "Norway", "iceland": "Iceland",
    "turkey": "Türkiye", "ukraine": "Ukraine", "albania": "Albania",
    "serbia": "Serbia", "montenegro": "Montenegro",
    "north macedonia": "North Macedonia",
    "bosnia and herzegovina": "Bosnia and Herzegovina", "moldova": "Moldova",
    "georgia": "Georgia", "armenia": "Armenia", "azerbaijan": "Azerbaijan",
    "russia": "Russia", "belarus": "Belarus", "kosovo": "Kosovo",
}

AGG_PARTS = ["euro area", "eurozone", "euro zone", "european union", "eu27",
             "eu 27", "eu", "europe", "world", "oecd", "g7", "g20", "total",
             "all countries", "extra eu", "intra eu", "non eu"]

COUNTRY_HEADERS = ["country", "geo", "region", "economy", "entity",
                   "member state", "territory", "nation", "location", "area"]
YEAR_HEADERS = ["year", "time", "period", "date", "time period",
                "observation time", "reporting period", "fiscal year"]
METRIC_HEADERS = ["indicator", "metric", "series", "measure", "variable",
                  "category", "subject", "item", "statistic", "data type",
                  "unit"]
VALUE_HEADERS = ["value", "values", "observation", "data", "amount", "level",
                 "figure", "obs value", "val"]
IGNORE_HEADERS = {"freq", "flags", "flag", "status", "label", "labels",
                  "note", "notes", "source", "unit label"}

PREFERRED = ["growth", "inflation", "unemployment", "gdppc", "gdp", "debt",
             "deficit", "trade", "investment", "employment"]


def norm(s):
    return re.sub(r"[^a-z0-9]+", " ", str(s).lower()).strip()


def to_number(v):
    if v is None:
        return None
    s = str(v).strip()
    s = s.replace(",", "").replace("%", "").replace("\u20ac", "").replace("$", "")
    s = s.replace("\u202f", "").replace("\xa0", "")
    if re.match(r"^[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?$", s):
        try:
            return float(s)
        except ValueError:
            return None
    return None


def looks_like_year(v):
    s = str(v).strip()
    if re.match(r"^[0-9]{4}$", s):
        n = int(s)
        if 1950 <= n <= 2100:
            return n
    return None


def find_metric(name):
    n = norm(name)
    best = None
    best_len = 0
    for key, aliases in METRIC_ALIASES.items():
        for a in aliases:
            if a in n and len(a) > best_len:
                best = key
                best_len = len(a)
    return best


def match_country(cell):
    c = norm(cell)
    best = None
    best_len = 0
    for name in COUNTRY_NAMES:
        n = norm(name)
        if n and n in c and len(n) > best_len:
            best = n
            best_len = len(n)
    return best


def find_country_in_row(cells):
    for cell in cells[:6]:
        k = match_country(cell)
        if k:
            return k
    return None


def is_aggregate(key):
    c = norm(key)
    return any(norm(p) in c for p in AGG_PARTS)


def label(key):
    if key in DISPLAY:
        return DISPLAY[key]
    return key.replace("_", " ").replace("-", " ").title()


def classify_header(h):
    n = norm(h)
    if looks_like_year(h) is not None:
        return "yearcol"
    if n in YEAR_HEADERS or any(y in n for y in ("time period", "observation time")):
        return "year"
    if any(c in n for c in COUNTRY_HEADERS):
        return "country"
    if any(m in n for m in METRIC_HEADERS):
        return "metric"
    if any(v in n for v in VALUE_HEADERS):
        return "value"
    m = find_metric(h)
    if m:
        return "metric_" + m
    return None


def promote_metric_cols(header, header_types, rows, value_cols):
    """Turn a repeated-code column (e.g. Eurostat 'unit') into a metric column."""
    for i in range(len(header)):
        if header_types[i] is not None:
            continue
        if norm(header[i]) in IGNORE_HEADERS:
            continue
        vals = [str(r[i]).strip() for r in rows if i < len(r) and str(r[i]).strip()]
        if not vals or not value_cols:
            continue
        numeric = sum(1 for v in vals if to_number(v) is not None)
        if numeric / len(vals) < 0.6 and len(set(vals)) <= 12:
            header_types[i] = "metric"


def process_matrix(header, rows, path):
    header = [str(h).strip() for h in header]
    header_types = [classify_header(h) for h in header]
    year_cols = [i for i, t in enumerate(header_types) if t == "year"]
    country_cols = [i for i, t in enumerate(header_types) if t == "country"]
    metric_cols = [i for i, t in enumerate(header_types) if t == "metric"]
    value_cols = [i for i, t in enumerate(header_types) if t == "value"]
    metric_map = {i: t[7:] for i, t in enumerate(header_types)
                  if t and t.startswith("metric_")}

    promote_metric_cols(header, header_types, rows, value_cols)
    metric_cols = [i for i, t in enumerate(header_types) if t == "metric"]

    metric_year = {}
    for i, h in enumerate(header):
        m = re.search(r"\b(19[5-9][0-9]|20[0-9][0-9])\b", h)
        if m and i in metric_map:
            metric_year[i] = int(m.group(1))

    wide_year_cols = [i for i, h in enumerate(header)
                      if looks_like_year(h) is not None]
    file_metric = find_metric(os.path.basename(path))

    records = []
    seen = set()
    for row in rows:
        row = [str(c) for c in row]
        country = None
        if country_cols and country_cols[0] < len(row):
            country = match_country(row[country_cols[0]]) or None
        if country is None:
            country = find_country_in_row(row[:6])
        year = None
        for ci in year_cols:
            if ci < len(row):
                y = looks_like_year(row[ci])
                if y is not None:
                    year = y
                    break

        if metric_cols and value_cols:
            mc = metric_cols[0]
            mname = row[mc] if mc < len(row) else ""
            m = find_metric(mname) or norm(mname) or "value"
            for vi in value_cols:
                if vi < len(row):
                    v = to_number(row[vi])
                    if v is not None:
                        rec = (country, year, m, v)
                        if rec not in seen:
                            seen.add(rec)
                            records.append({"country": country, "year": year,
                                            "metric": m, "value": v,
                                            "file": os.path.basename(path)})
        elif metric_map:
            for ci, m in metric_map.items():
                if ci >= len(row):
                    continue
                v = to_number(row[ci])
                if v is None:
                    continue
                y = metric_year.get(ci, year)
                rec = (country, y, m, v)
                if rec not in seen:
                    seen.add(rec)
                    records.append({"country": country, "year": y,
                                    "metric": m, "value": v,
                                    "file": os.path.basename(path)})
        elif metric_cols and wide_year_cols:
            mc = metric_cols[0]
            mname = row[mc] if mc < len(row) else ""
            m = find_metric(mname) or norm(mname) or (file_metric or "value")
            for ci in wide_year_cols:
                v = to_number(row[ci]) if ci < len(row) else None
                if v is not None:
                    y = looks_like_year(header[ci])
                    rec = (country, y, m, v)
                    if rec not in seen:
                        seen.add(rec)
                        records.append({"country": country, "year": y,
                                        "metric": m, "value": v,
                                        "file": os.path.basename(path)})
        elif value_cols:
            for vi in value_cols:
                if vi < len(row):
                    v = to_number(row[vi])
                    if v is not None:
                        m = file_metric or "value"
                        rec = (country, year, m, v)
                        if rec not in seen:
                            seen.add(rec)
                            records.append({"country": country, "year": year,
                                            "metric": m, "value": v,
                                            "file": os.path.basename(path)})
        elif wide_year_cols:
            for ci in wide_year_cols:
                v = to_number(row[ci]) if ci < len(row) else None
                if v is not None:
                    y = looks_like_year(header[ci])
                    m = file_metric or "value"
                    rec = (country, y, m, v)
                    if rec not in seen:
                        seen.add(rec)
                        records.append({"country": country, "year": y,
                                        "metric": m, "value": v,
                                        "file": os.path.basename(path)})
    return records


def parse_csv_file(path):
    with open(path, newline="", encoding="utf-8-sig", errors="replace") as f:
        sample = f.read(16384)
        f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
        except csv.Error:
            dialect = csv.excel
        reader = csv.reader(f, dialect)
        header = None
        rows = []
        for line in reader:
            if not line or all(not str(c).strip() for c in line):
                continue
            if header is None:
                header = [str(c).strip() for c in line]
                continue
            if len(line) < len(header):
                line = list(line) + [""] * (len(header) - len(line))
            rows.append(line[:len(header)])
    if header is None or not rows:
        return []
    nums = sum(1 for r in rows for c in r if to_number(c) is not None)
    if len(header) < 2 or nums < 2:
        return []
    return process_matrix(header, rows, path)


def json_to_matrix(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    rows = []
    if isinstance(data, dict):
        if "data" in data and isinstance(data["data"], list):
            data = data["data"]
        else:
            for k, v in data.items():
                if isinstance(v, dict):
                    r = {"country": k}
                    r.update({str(kk): vv for kk, vv in v.items()})
                    rows.append(r)
                else:
                    rows.append({"label": k, "value": v})
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                rows.append({str(k): v for k, v in item.items()})
    if not rows:
        return []
    header = list(rows[0].keys())
    matrix = [[r.get(h, "") for h in header] for r in rows]
    return process_matrix(header, matrix, path)


def discover_files():
    found = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames
                       if not d.startswith(".") and d != "__pycache__"]
        for fn in sorted(filenames):
            if fn.startswith("."):
                continue
            ext = os.path.splitext(fn)[1].lower()
            if ext in (".csv", ".tsv", ".txt", ".json", ".jsonl"):
                found.append(os.path.join(dirpath, fn))
    return found


# --------------------------------------------------------------------------
# Analysis
# --------------------------------------------------------------------------

def analyze(records):
    buckets = defaultdict(lambda: defaultdict(list))
    for r in records:
        if r["country"] and r["metric"] and r["value"] is not None:
            buckets[r["metric"]][r["country"]].append((r["year"], r["value"]))
    results = {}
    for m, pairs in buckets.items():
        series = {c: sorted(lst) for c, lst in pairs.items()}
        yrs = Counter(y for lst in series.values() for y, _ in lst
                      if y is not None)
        best = None
        for y, cnt in yrs.items():
            if y < 1990:
                continue
            if best is None or cnt > best[1] or (cnt == best[1] and y > best[0]):
                best = (y, cnt)
        snap_year = best[0] if best else None
        snap = {}
        if snap_year is not None:
            for c, lst in series.items():
                for y, v in lst:
                    if y == snap_year:
                        snap.setdefault(c, v)
        if not snap:
            for c, lst in series.items():
                if lst:
                    snap[c] = lst[-1][1]
            snap_year = max((lst[-1][0] for lst in series.values()
                             if lst and lst[-1][0] is not None), default=None)
        results[m] = {"series": series, "snap": snap, "snap_year": snap_year}
    return results


def aggregate_value(results, m):
    info = results.get(m)
    if not info:
        return None
    for c, v in info["snap"].items():
        if is_aggregate(c):
            return (c, v, info["snap_year"])
    return None


def correlation(metric_a, metric_b, results):
    sa = results.get(metric_a, {}).get("snap", {})
    sb = results.get(metric_b, {}).get("snap", {})
    keys = [c for c in sa if c in sb and not is_aggregate(c)]
    if len(keys) < 3:
        return None
    xs = [sa[c] for c in keys]
    ys = [sb[c] for c in keys]
    n = len(xs)
    mx = sum(xs) / n
    my = sum(ys) / n
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    dy = math.sqrt(sum((y - my) ** 2 for y in ys))
    if dx == 0 or dy == 0:
        return None
    return num / (dx * dy)


def trend_summary(results, m):
    deltas = {}
    for c, lst in results[m]["series"].items():
        if is_aggregate(c):
            continue
        if (len(lst) >= 2 and lst[0][0] is not None and lst[-1][0] is not None
                and lst[0][0] != lst[-1][0]):
            deltas[c] = (lst[0], lst[-1])
    return deltas


def spread_evolution(m, results):
    series = results[m]["series"]
    years = sorted({y for lst in series.values() for y, _ in lst
                    if y is not None and y >= 1990})
    evo = []
    for y in years:
        vals = [v for c, lst in series.items() if not is_aggregate(c)
                for yy, v in lst if yy == y]
        if len(vals) >= 4:
            evo.append((y, max(vals) - min(vals), max(vals), min(vals)))
    return evo


def pick_primary(results):
    for m in PREFERRED:
        if m in results:
            cnt = sum(1 for c in results[m]["snap"] if not is_aggregate(c))
            if cnt >= 3:
                return m, cnt
    best = None
    for m, info in results.items():
        cnt = sum(1 for c in info["snap"] if not is_aggregate(c))
        if best is None or cnt > best[1]:
            best = (m, cnt)
    if best and best[1] >= 1:
        return best
    return None, 0


# --------------------------------------------------------------------------
# Output helpers
# --------------------------------------------------------------------------

def table(headers, rows):
    out = ["| " + " | ".join(headers) + " |",
           "| " + " | ".join(["---"] * len(headers)) + " |"]
    for r in rows:
        out.append("| " + " | ".join(str(c) for c in r) + " |")
    return "\n".join(out)


def bars(items, width=26, unit="%", name_w=24):
    lines = []
    vmax = max((abs(v) for _, v in items), default=0) or 1.0
    for name, v in items:
        n = int(round(abs(v) / vmax * width))
        lines.append("`" + f"{name:<{name_w}}" + " " + "\u2588" * n
                     + " " * (width - n) + f" {v:+,.1f}{unit}" + "`")
    return "\n".join(lines)


def snapshot_table(metric, results, limit=None, exclude_agg=True, sort_desc=True):
    info = results[metric]
    snap = info["snap"]
    unit = METRIC_UNIT.get(metric, "")
    items = [(c, v) for c, v in snap.items()
             if not (exclude_agg and is_aggregate(c))]
    items.sort(key=lambda t: t[1], reverse=sort_desc)
    if limit:
        items = items[:limit]
    if not items:
        return "", []
    avg = sum(v for _, v in items) / len(items)
    rows = []
    for c, v in items:
        rows.append([label(c), f"{v:+,.2f} {unit}".strip(),
                     f"{v - avg:+,.2f} vs avg"])
    return (table(["Economy",
                   f"{METRIC_DISPLAY.get(metric, metric)} ({info['snap_year']})",
                   "Gap to average"], rows), items)


def build_hook(primary, results):
    if primary is None:
        return ("The files in this directory carry the raw material of a story "
                "about Europe's economy — but the narrative has to be assembled "
                "from the numbers.")
    info = results[primary]
    snap = info["snap"]
    year = info["snap_year"]
    unit = METRIC_UNIT.get(primary, "")
    mname = METRIC_DISPLAY.get(primary, primary)
    countries = {c: v for c, v in snap.items() if not is_aggregate(c)}
    if len(countries) >= 2:
        top = max(countries, key=countries.get)
        bot = min(countries, key=countries.get)
        spread = countries[top] - countries[bot]
        return (f"**{label(top)}** recorded {countries[top]:+.2f}{unit} "
                f"{mname} in {year} while **{label(bot)}** was at "
                f"{countries[bot]:+.2f}{unit} — a {spread:+.2f}-point gap "
                f"that defines Europe's uneven economic performance.")
    agg = aggregate_value(results, primary)
    if agg:
        return (f"In {year}, **{label(agg[0])}** posted {agg[1]:+.2f}{unit} "
                f"{mname} — the baseline against which every national story "
                f"is told.")
    return (f"Across {len(snap)} economies, **{mname}** is the indicator that "
            f"best captures Europe's economic performance in {year}.")


# --------------------------------------------------------------------------
# Report generation
# --------------------------------------------------------------------------

def build_report(results, meta, records):
    primary, _pcount = pick_primary(results)
    L = []

    # ---- Title / hook ----------------------------------------------------
    L.append("# The European Economy, Told in Data")
    L.append("")
    L.append("> **A data-story report generated from the economic datasets in "
             "this directory.**")
    L.append("")
    L.append("## The Hook")
    L.append("")
    L.append(build_hook(primary, results))
    L.append("")

    # ---- 1. Setup --------------------------------------------------------
    L.append("## 1 · The Setup — Where Europe Stands")
    L.append("")
    n_countries = sum(1 for c in meta["countries"] if not is_aggregate(c))
    n_agg = len(meta["countries"]) - n_countries
    scope = (f"**{n_countries} national economies**"
             + (f" plus **{n_agg} aggregate grouping(s)** (EU, euro area, etc.)"
                if n_agg else "")
             + f" over **{meta['y0']}–{meta['y1']}**")
    L.append(f"This report is assembled from **{meta['n_records']:,} data "
             f"points** across **{len(meta['files'])} file(s)** found in this "
             f"directory, covering {scope}.")
    L.append("")
    metrics_txt = ", ".join(METRIC_DISPLAY.get(m, m) for m in meta["metrics"]) or "—"
    L.append(f"Indicators tracked: **{metrics_txt}**.")
    L.append("")
    if primary:
        agg = aggregate_value(results, primary)
        mname = METRIC_DISPLAY.get(primary, primary)
        unit = METRIC_UNIT.get(primary, "")
        if agg:
            L.append(f"**Baseline:** in {agg[2]}, **{label(agg[0])}** recorded "
                     f"{agg[1]:+,.2f}{unit} {mname}. That is the reference "
                     f"point every national story is measured against.")
        else:
            L.append(f"**Baseline:** the most recent snapshot of **{mname}** "
                     f"is from **{results[primary]['snap_year']}**, covering "
                     f"{len(results[primary]['snap'])} entities.")
        L.append("")

    # ---- 2. Conflict -----------------------------------------------------
    L.append("## 2 · The Conflict — A Continent Pulling Apart")
    L.append("")
    if primary:
        tbl, items = snapshot_table(primary, results, limit=10)
        if items:
            L.append(f"The clearest tension is in **{METRIC_DISPLAY.get(primary, primary)}** "
                     f"({results[primary]['snap_year']}): the gap between the "
                     f"best- and worst-performing economies is the story.")
            L.append("")
            L.append(tbl)
            L.append("")
            top5 = items[:5]
            bot5 = list(reversed(items[-5:])) if len(items) > 5 else []
            chart_items = top5 + bot5
            if chart_items:
                L.append("**Leaders vs. laggards at a glance:**")
                L.append("")
                L.append(bars(chart_items, unit=METRIC_UNIT.get(primary, "")))
                L.append("")
    evo = spread_evolution(primary, results) if primary else []
    if len(evo) >= 2:
        first = evo[0]
        last = evo[-1]
        delta = last[1] - first[1]
        if delta > 0:
            trend_line = ("The gap is **widening** — and that widening is the "
                          "real headline.")
        else:
            trend_line = ("The gap is **narrowing** — convergence is "
                          "underway.")
        L.append(f"The divide is **not static**: measured on years where at "
                 f"least four economies report, the spread (best minus worst) "
                 f"moved from **{first[1]:+.2f} pts in {first[0]}** to "
                 f"**{last[1]:+.2f} pts in {last[0]}** ({delta:+.2f} pts). "
                 f"{trend_line}")
        L.append("")

    # ---- 3. Climax / insight ---------------------------------------------
    L.append("## 3 · The Climax — The Key Insight")
    L.append("")
    ins = []
    if primary:
        countries = {c: v for c, v in results[primary]["snap"].items()
                     if not is_aggregate(c)}
        if len(countries) >= 2:
            top = max(countries, key=countries.get)
            bot = min(countries, key=countries.get)
            unit = METRIC_UNIT.get(primary, "")
            ins.append(f"**The leader is {label(top)}** "
                       f"({countries[top]:+,.2f}{unit}), **the laggard is "
                       f"{label(bot)}** ({countries[bot]:+,.2f}{unit}). "
                       f"Where an economy sits in Europe still predicts a "
                       f"large part of its economic outcome.")
        deltas = trend_summary(results, primary)
        if deltas:
            imp = sum(1 for (_a, b) in deltas.values() if (b[1] - _a[1]) > 0)
            dec = len(deltas) - imp
            mname = METRIC_DISPLAY.get(primary, primary).lower()
            ins.append(f"Over the period covered, **{imp} of {len(deltas)} "
                       f"economies improved** their {mname} while {dec} moved "
                       f"in the other direction — momentum is real but "
                       f"uneven.")
    corr = None
    corr_desc = ""
    for a, b, desc in [("growth", "unemployment", "growth and unemployment"),
                       ("growth", "inflation", "growth and inflation"),
                       ("inflation", "unemployment", "inflation and unemployment")]:
        c = correlation(a, b, results)
        if c is not None:
            corr = c
            corr_desc = desc
            break
    if corr is not None:
        strength = "strong" if abs(corr) >= 0.6 else (
            "moderate" if abs(corr) >= 0.35 else "weak")
        direction = "positive" if corr > 0 else "negative"
        if corr_desc == "growth and unemployment" and corr < 0:
            follow = ("The classic trade-off shows up in the data: where "
                      "growth is stronger, unemployment tends to be lower.")
        elif corr_desc == "inflation and unemployment" and corr < 0:
            follow = ("The data hints at the familiar inflation–unemployment "
                      "tension: the two rarely move together.")
        else:
            follow = "That relationship is worth watching in the next review cycle."
        ins.append(f"A **{strength} {direction} correlation** "
                   f"(r \u2248 {corr:+.2f}) links {corr_desc} across the "
                   f"sample. {follow}")
    if ins:
        L.append("\n\n".join(ins))
    else:
        L.append("The data in this directory is too sparse to isolate a single "
                 "headline insight; the snapshot tables in the appendix are "
                 "the most reliable reading of what the files contain.")
    L.append("")

    # ---- 4. Resolution ---------------------------------------------------
    L.append("## 4 · The Resolution — What the Data Suggests")
    L.append("")
    rec = []
    if primary:
        countries = {c: v for c, v in results[primary]["snap"].items()
                     if not is_aggregate(c)}
        if len(countries) >= 5:
            ordered = sorted(countries, key=countries.get, reverse=True)
            top3 = ", ".join(label(c) for c in ordered[:3])
            bot3 = ", ".join(label(c) for c in ordered[-3:])
            rec.append(f"**Replicate the leaders.** {top3} show what works; "
                       f"their practices are the template for the rest.")
            rec.append(f"**Target the laggards.** {bot3} explain most of the "
                       f"widening spread; support here has the highest "
                       f"marginal impact.")
    rec.append("**Read the countries, not just the aggregates.** EU-wide "
               "averages hide divergence; decisions should be made at the "
               "level where the numbers actually move.")
    rec.append("**Keep the comparisons honest.** Use consistent definitions "
               "(growth, inflation, unemployment) across all economies so the "
               "ranking stays apples-to-apples.")
    L.append("\n\n".join("- " + r for r in rec))
    L.append("")

    # ---- 5. Call to action ------------------------------------------------
    L.append("## 5 · The Call to Action")
    L.append("")
    L.append("- **Review these indicators quarterly** against the snapshots in "
             "Appendix A — the spread will tell you when the story changes.")
    L.append("- **Investigate the divide**: quantify why leaders outperform "
             "and laggards fall behind.")
    L.append("- **Set a convergence target** and track it in the next "
             "data-story report.")
    L.append("")

    # ---- Appendices -------------------------------------------------------
    L.append("---")
    L.append("## Appendix A · Indicator Snapshots")
    L.append("")
    cov_rows = []
    any_table = False
    for m in sorted(results, key=lambda x: METRIC_DISPLAY.get(x, x)):
        cnt = sum(1 for c in results[m]["snap"] if not is_aggregate(c))
        cov_rows.append([METRIC_DISPLAY.get(m, m), str(cnt),
                         str(results[m]["snap_year"])])
        if cnt >= 2:
            tbl, _ = snapshot_table(m, results, limit=8)
            if tbl:
                any_table = True
                L.append(f"### {METRIC_DISPLAY.get(m, m)} — snapshot "
                         f"{results[m]['snap_year']}")
                L.append("")
                L.append(tbl)
                L.append("")
    if not any_table:
        L.append("No indicator had two or more economies in a shared snapshot "
                 "year; see the coverage table below.")
        L.append("")
    L.append("### Coverage")
    L.append("")
    L.append(table(["Indicator", "Economies in snapshot", "Snapshot year"],
                   cov_rows))
    L.append("")
    L.append("## Appendix B · Data Coverage & Method")
    L.append("")
    L.append("**Data files used:**")
    L.append("")
    rows = [[os.path.relpath(f, ROOT), str(n)] for f, n in meta["file_stats"]]
    L.append(table(["File", "Parsed records"], rows))
    L.append("")
    L.append("**Method note.** Records were normalized to (economy, year, "
             "metric, value) using column-name heuristics and repeated-code "
             "detection. Aggregates (EU, euro area, Europe, etc.) are shown "
             "for context but excluded from country rankings. Values are "
             "reported as published in the source files; units follow the "
             "metric conventions listed above. Observations duplicated across "
             "files are de-duplicated. Where a series had no country column, "
             "the region as a whole was used as the unit of analysis.")
    L.append("")

    return "\n".join(L)


# --------------------------------------------------------------------------
# Entry point
# --------------------------------------------------------------------------

def main():
    files = discover_files()
    if not files:
        print("No data files found in the directory.", file=sys.stderr)
        return 1

    all_records = []
    file_stats = []
    for f in files:
        try:
            if f.lower().endswith(".json") or f.lower().endswith(".jsonl"):
                recs = json_to_matrix(f)
            else:
                recs = parse_csv_file(f)
        except Exception as exc:  # noqa: BLE001 - keep going on bad files
            print("skipping {}: {}".format(os.path.basename(f), exc),
                  file=sys.stderr)
            recs = []
        all_records.extend(recs)
        if recs:
            file_stats.append((os.path.relpath(f, ROOT), len(recs)))

    if not all_records:
        print("Parsed no usable records from the data files.", file=sys.stderr)
        return 1

    if not any(r["country"] for r in all_records):
        for r in all_records:
            r["country"] = "europe"

    results = analyze(all_records)

    meta = {
        "files": files,
        "file_stats": file_stats,
        "n_records": len(all_records),
        "countries": sorted({r["country"] for r in all_records
                             if r["country"]}),
        "y0": min((r["year"] for r in all_records if r["year"] is not None),
                  default=None),
        "y1": max((r["year"] for r in all_records if r["year"] is not None),
                  default=None),
        "metrics": sorted({r["metric"] for r in all_records}),
    }

    try:
        report = build_report(results, meta, all_records)
    except Exception as exc:  # noqa: BLE001 - fall back to a minimal report
        print("report build error: {}".format(exc), file=sys.stderr)
        report = ("# The European Economy, Told in Data\n\n"
                  "A minimal report was generated because the full narrative "
                  "builder hit an error. See stdout for the data inventory.\n")

    with open(REPORT_PATH, "w", encoding="utf-8") as fh:
        fh.write(report)

    print("=== EUROPEAN ECONOMIC DATA INVENTORY ===")
    for f, n in file_stats:
        print("  {}: {} records".format(f, n))
    print("Total records: {}".format(len(all_records)))
    print("Economies: {}".format(len(meta["countries"])))
    print("Years: {}–{}".format(meta["y0"], meta["y1"]))
    print("Metrics: {}".format(", ".join(meta["metrics"])))
    for m, info in results.items():
        n = sum(1 for c in info["snap"] if not is_aggregate(c))
        print("  [{}] snapshot year {}, {} countries".format(
            m, info["snap_year"], n))
    print("Report written to: {}".format(REPORT_PATH))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Task-scoped helper for the data-storytelling report on European economic
performance. Discovers data files in this directory, normalizes them into
(economy, year, metric, value) records, computes narrative insights, and
writes a Markdown data-story report following the data-storytelling
framework (Hook -> Setup -> Conflict -> Insight -> Resolution -> Action).
"""

import csv
